    "type": "add",
    "content": """"Operate the single live CEOBench session through its documented CLI."""

import argparse
import json
import re
import subprocess
from pathlib import Path

from policy import make_plan


SESSION = "00b8448d6891"
CLI = "./novamind-operation"
STRATEGY = Path("strategy")
RECORDS = STRATEGY / "observations"


def command(name, *args):
    return [CLI, name, "--session", SESSION, *map(str, args)]


def capture(name, *args):
    return subprocess.run(command(name, *args), text=True, capture_output=True, check=True)


def read_status():
    return json.loads(capture("status").stdout)


def stream(name, *args):
    with subprocess.Popen(
        command(name, *args),
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=1,
    ) as process:
        lines = []
        for line in process.stdout:
            print(line, end="", flush=True)
            lines.append(line)
        return process.wait(), "".join(lines)


def report_request(request_id):
    try:
        result = capture("request-status", request_id)
    except subprocess.CalledProcessError as error:
        print(error.stderr or error.stdout, flush=True)
        return
    print(result.stdout, end="", flush=True)


def advance_to(until):
    RECORDS.mkdir(exist_ok=True)
    while True:
        status = read_status()
        day = status["current_day"]
        cash = status["cash"]
        if day >= until or day >= 500 or cash <= 0:
            return
        if not status["server_running"]:
            raise RuntimeError(f"Check documented resume before continuing at day {day}, cash {cash}")

        observed = json.loads(capture("python", STRATEGY / "observe.py").stdout)
        if observed["day"] != day:
            raise RuntimeError("Committed day changed while the weekly observation was running")

        (RECORDS / f"day-{day:03d}.json").write_text(json.dumps(observed, indent=2))
        plan, rationale, forecasts = make_plan(observed, RECORDS)
        week = day // 7 + 1
        request_id = f"w{week:03d}"
        (STRATEGY / "weekly_plan.json").write_text(json.dumps(plan, indent=2))
        print(f"Day {day}, cash ${cash:,.2f}. {rationale}", flush=True)

        if len(plan) > 1:
            result, output = stream("python", STRATEGY / "act.py")
            if result:
                ids = re.findall(r'"request_id": "([^"]+)"', output)
                if ids:
                    report_request(ids[-1])
                raise RuntimeError("Weekly actions interrupted. Inspect the reported request status.")

        result, output = stream("next-week", "--request-id", request_id, rationale, *forecasts)
        (RECORDS / f"week-{week:03d}.txt").write_text(output)
        if result:
            report_request(request_id)
            raise RuntimeError(f"Advance {request_id} interrupted. Inspect the reported request status.")

        after = read_status()
        if after["current_day"] <= day and after["cash"] > 0:
            raise RuntimeError(f"Advance {request_id} did not report a new committed day.")
        print(f"Committed day {after['current_day']}, cash ${after['cash']:,.2f}", flush=True)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--until", type=int, default=500)
    advance_to(parser.parse_args().until)
