from collections import Counter, defaultdict
from math import ceil
import json


RETAIL = ("S1", "S2", "S3")
PLANS = ("A", "B", "C")
CHANNELS = ("referral_program", "content_marketing", "social_media", "search_ads")
CAPACITIES = (50000, 200000, 800000, 2500000, 8000000, 25000000, 80000000, 300000000)
CAPACITY_COSTS = (85, 215, 530, 1330, 4000, 10000, 28000, 75000)
DEFAULT_MARKET_SIZES = {"S1": 325000, "S2": 170000, "S3": 75000}
ENTERPRISE_PRICE = {"E1": 16, "E2": 49, "E3": 73}


def retail_summary(observed):
    groups = defaultdict(Counter)
    for row in observed["retail"]:
        groups[row["group_id"]].update({
            key: value or 0 for key, value in row.items() if key not in ("group_id", "plan")
        })
    return groups


def parse_latest_quality(records, day):
    if day == 56:
        file = records / "week-008.txt"
    else:
        file = records / f"week-{ceil(day / 7):03d}.txt"
    quality = {}
    if file.exists():
        for line in file.read_text().splitlines():
            fields = line.split()
            if len(fields) == 5 and fields[0].startswith(("S", "E", "D_")):
                try:
                    quality[fields[0]] = float(fields[1])
                except ValueError:
                    continue
    return quality


def ads_policy(observed, retail, discovered, quality, old_advertising):
    day = observed["day"]
    old_paid = defaultdict(list)
    for row in observed["paid"]:
        old_paid[row["group_id"]].append(row)

    budgets = defaultdict(dict)
    expected_starts = {}
    expected_new_receipts = 0.0
    for group in retail.keys() | {group for group in discovered if group.startswith("D_S")}:
        metrics = retail[group]
        paid = old_paid[group]
        leads = metrics["leads"]
        prior_spend = sum(row["spend"] for row in paid)
        paid_leads = sum(row["leads"] for row in paid)
        organic = max(0, leads - paid_leads)
        conversion = metrics["joined"] / max(1, leads)
        income_per_lead = metrics["new_mrr"] / max(1, leads)
        first_bill_per_ad_dollar = income_per_lead * paid_leads / max(1, prior_spend)
        age = day - discovered.get(group, 0)
        current = {channel: groups[group] for channel, groups in old_advertising.items() if group in groups}
        prior_budget = sum(current.values())
        best_channel = max(paid, key=lambda row: row["leads"] / max(1, row["spend"]))["channel_id"] if paid else None
        chosen = {}

        if group in RETAIL:
            max_budget = {"S1": 115000, "S2": 155000, "S3": 95000}[group]
            best_channel = best_channel or ("content_marketing" if group == "S2" else "referral_program")
            factor = 1.52 if first_bill_per_ad_dollar >= 2.4 else 1.10
            if first_bill_per_ad_dollar < 1.0:
                factor = 0.72
            if day > 420:
                factor = min(factor, 1.12)
            if day > 470 and first_bill_per_ad_dollar < 1.45:
                factor = min(factor, 0.55)
            chosen[best_channel] = min(max_budget, max(1200, round(prior_budget * factor / 100) * 100))
        elif day < 475 and (age >= 14 or quality.get(group, 0) >= 0.28):
            if not paid or age < 21 and conversion < 0.20:
                chosen = {channel: 450 for channel in CHANNELS}
            elif first_bill_per_ad_dollar >= 1.65:
                factor = 2.0 if prior_budget < 18000 else 1.25
                chosen[best_channel] = min(35000, max(4000, round(prior_budget * factor / 100) * 100))
            elif first_bill_per_ad_dollar >= 0.70:
                chosen[best_channel] = max(900, round(prior_budget * 0.84 / 100) * 100)
            else:
                chosen[best_channel] = min(1800, max(450, round(prior_budget * 0.45 / 100) * 100))

        if day >= 490 and first_bill_per_ad_dollar < 1.15:
            chosen = {}
        for channel, amount in chosen.items():
            budgets[channel][group] = amount
        projected_paid = paid_leads * sum(chosen.values()) / max(1, prior_budget)
        if not paid and chosen:
            projected_paid = sum(chosen.values()) * 7 * 0.065
        projected_leads = organic + projected_paid * 0.93
        if metrics["active"] + projected_leads * conversion > DEFAULT_MARKET_SIZES.get(group, 110000):
            projected_leads = organic + projected_paid * 0.65
        expected_starts[group] = projected_leads * conversion
        expected_new_receipts += projected_leads * income_per_lead

    return dict(budgets), expected_starts, expected_new_receipts


def enterprise_offers(observed, quality):
    deals = []
    seen = set()
    ordered = sorted(observed["enterprise"], key=lambda row: (
        row["thread_type"] != "new_lead", row["seat_count"], row["day"]
    ), reverse=True)
    for thread in ordered:
        group = thread["group_id"]
        customer = thread["customer_id"]
        if customer in seen or quality.get(group, 0.0) < 0.33:
            continue
        if thread["day"] <= observed["day"] - 7:
            continue
        seen.add(customer)
        baseline = ENTERPRISE_PRICE.get(group, 42)
        offered = json.loads(thread["offer_json"] or "{}")
        if not isinstance(offered, dict):
            offered = {}
        known_budget = next((
            offered[key] for key in ("max_price", "price_per_seat", "price")
            if isinstance(offered.get(key), (int, float)) and offered[key] > 0
        ), None)
        if known_budget is not None:
            baseline = min(baseline * 1.35, known_budget * 1.02)
        if thread["turn_number"] > 0:
            baseline *= 0.88
        if thread["thread_type"] in ("renewal", "churn_prevention"):
            baseline *= 0.88
        plan = "A" if quality[group] >= 0.72 or group == "E1" else "B"
        deals.append([customer, [[plan, round(max(7, baseline), 2)]]])
        if len(deals) == 50:
            break
    return deals


def make_forecasts(observed, plan, retail, starts, new_receipts, total_operations, global_dev, dev, capacity):
    day = observed["day"]
    prices = plan.get("prices") or {name: observed["config"][f"price_{name}"] for name in PLANS}
    recent = Counter()
    for row in observed["ledger"]:
        if row["day"] > day - 7:
            recent[row["category"]] += row["amount"]
    active = sum(group["active"] for group in retail.values())
    current_mrr = sum(row["active"] * prices[row["plan"]] for row in observed["retail"])
    current_mrr += sum(row["mrr"] for row in observed["enterprise_book"])
    due = sum(
        row["seats"] * prices[row["plan"]] if row["customer_type"] == "small" else row["mrr"]
        for row in observed["due"]
    )
    adjusted_acquisitions = sum(starts.values())
    cap_growth = min(adjusted_acquisitions, 130000)
    compute = -recent["compute"] * (active + cap_growth / 2) / max(1, active - sum(
        group["joined"] for group in retail.values()
    ) / 2)
    ad_spend = sum(amount for group in plan.get("advertising", {}).get("targeted_spend", {}).values() for amount in group.values())
    if "advertising" not in plan:
        ad_spend = observed["config"]["spend_advertising"]
    fixed = 7 * (total_operations + global_dev + sum(dev.values()) + CAPACITY_COSTS[capacity] + ad_spend)
    uncertain_receipts = new_receipts * 0.95
    near_gain = due * 0.96 + uncertain_receipts - fixed - compute + recent["ad_revenue"] - adjusted_acquisitions * 0.65
    daily_run_rate = current_mrr / 30 - (
        compute / 7 + total_operations + CAPACITY_COSTS[capacity] + global_dev + sum(dev.values())
    )
    discovery_cost = 25000 * plan.get("discovery_attempts", 0)
    project_cost = sum(round(tier * 166666.7) for tier in plan.get("research", []))
    cash = observed["cash"] - discovery_cost - project_cost
    growth_cash = max(0, uncertain_receipts - ad_spend * 7)
    forecasts = []
    for horizon in (7, 28, 84, 182):
        modeled_days = min(horizon, 500 - day)
        if horizon == 7:
            point = cash + near_gain * modeled_days / 7
            width = max(15000, min(0.6, 40000 / max(active, 1) + 0.13) * abs(uncertain_receipts) + 0.07 * due)
        else:
            growth = growth_cash * min(17, modeled_days / 7) * (0.8 + min(1.7, modeled_days / 120))
            point = cash + modeled_days * daily_run_rate * 0.98 + growth
            width = max(45000, abs(point - cash) * (0.22 + min(0.35, horizon / 320)))
        lower = max(0, point - width)
        point = max(lower, point)
        forecasts.extend(round(value, 2) for value in (point, lower, point + width))
    return forecasts


def make_plan(observed, records):
    day, cash, config = (observed[key] for key in ("day", "cash", "config"))
    retail = retail_summary(observed)
    active = sum(group["active"] for group in retail.values())
    seats = sum(group["seats"] for group in observed["enterprise_book"])
    discovered = {row["group_id"]: row["discovered_day"] for row in observed["discovered"]}
    quality = parse_latest_quality(records, day)
    overrides = {row["setting_type"]: json.loads(row["settings_json"]) for row in observed["overrides"]}
    old_ads = overrides.get("targeted_ad_spend", {}).get("targeted_spend", {})
    old_dev = overrides.get("targeted_dev_spend", {}).get("targeted_spend", {})

    plan = {"day": day}
    if day == 56:
        plan["prices"] = {"A": 26, "B": 85, "C": 174}
    elif day == 70:
        plan["prices"] = {"A": 27, "B": 91, "C": 186}
    elif day == 91:
        plan["prices"] = {"A": 28, "B": 96, "C": 198}

    if day < 112 and cash > 4_000_000 and len(discovered) < 26:
        plan["discovery_attempts"] = min(18, (26 - len(discovered)) * 3)
    if day == 56 and cash > 7_000_000:
        plan["research"] = [9]
    if day == 70 and cash > 13_000_000 and max(quality.get(g, 0) for g in RETAIL) < 1.5:
        plan["research"] = [8]

    budgets, starts, new_receipts = ads_policy(observed, retail, discovered, quality, old_ads)
    if day == 56:
        budgets["linkedin"] = {"E1": 120, "E2": 180, "E3": 120}
    elif day >= 63 and day < 450:
        target = {
            group: amount for group, amount in {"E1": 550, "E2": 950, "E3": 600}.items()
            if quality.get(group, 0) >= {"E1": 0.48, "E2": 0.55, "E3": 0.50}[group]
        }
        if target:
            budgets["linkedin"] = target
    if budgets != old_ads:
        plan["advertising"] = {"targeted_spend": budgets}

    dev = {}
    for group, discovered_day in discovered.items():
        q = quality.get(group)
        if group in RETAIL:
            dev[group] = 1500 if q is None or q < 0.95 else 0
        elif group.startswith("D_S"):
            dev[group] = 6800 if q is None or q < 0.57 else 2000 if q < 0.76 else 0
        elif group in ENTERPRISE_PRICE:
            dev[group] = 7200 if q is None or q < 0.65 else 1600 if q < 0.85 else 0
        elif day < 210 and day - discovered_day >= 14 and (q is None or q < 0.45):
            dev[group] = 2500
    if day >= 350:
        dev = {}
    if {k: v for k, v in dev.items() if v} != {k: v for k, v in old_dev.items() if v}:
        plan["development"] = {"targeted_spend": dev}

    growth = max(0, sum(starts.values()))
    issue_count = sum(row["new"] or 0 for row in observed["support"])
    support_backlog = sum(row["open"] or 0 for row in observed["support"])
    last_average_active = active - sum(group["joined"] for group in retail.values()) / 2
    issue_rate = min(0.15, issue_count / (7 * max(1, last_average_active)))
    projected_issues = issue_rate * (active + growth / 2)
    operations = max(2500, round((1.01 * projected_issues + max(0, support_backlog - active * 0.08) / 7) / 0.3 / 500) * 500)
    global_dev = 37000 if day < 119 else 22000 if day < 231 else 7000 if day < 385 else 0
    if operations != config["spend_operations"] or global_dev != config["spend_development"]:
        plan["spend"] = {"operations": operations, "development": global_dev}

    peak = max(row["total_usage_units"] for row in observed["usage"][-7:])
    projected_peak = peak * (1.14 + growth / max(1, active + seats))
    capacity = next((tier for tier, limit in enumerate(CAPACITIES) if limit >= projected_peak), 7)
    if capacity != config["capacity_tier"] and (
        capacity > config["capacity_tier"] or projected_peak < CAPACITIES[capacity] * 0.72
    ):
        plan["capacity"] = {"tier": capacity}
    else:
        capacity = config["capacity_tier"]

    deals = enterprise_offers(observed, quality)
    if deals:
        plan["deals"] = {"deals": deals}

    advertising = sum(sum(group.values()) for group in budgets.values())
    price_note = (
        f" Test new retail prices of ${plan['prices']['A']}, ${plan['prices']['B']}, and ${plan['prices']['C']} against realized revenue per lead."
        if "prices" in plan else " Keep retail prices steady to measure renewal and acquisition performance."
    )
    research_note = ""
    if plan.get("discovery_attempts"):
        research_note += f" Allocate ${25000 * plan['discovery_attempts']:,} to discovering additional segments."
    if plan.get("research"):
        research_note += f" Start shared quality research at tier {plan['research'][0]}."
    if not deals:
        deals_note = ""
    else:
        deals_note = f" Send {len(deals)} enterprise offers using segment budgets and observed terms."
    rationale = (
        f"Day {day} cash is ${cash:,.0f}, with {active:,} retail accounts and {seats:,} enterprise seats. "
        f"Allocate ${advertising:,.0f} per day to channels based on first-bill payback, "
        f"set operations to ${operations:,.0f} against {issue_count:,} new issues last week, "
        f"and plan capacity tier {capacity} against a {peak:,}-unit recent peak."
        f"{price_note}{research_note}{deals_note} Review conversion, renewal receipts and service load at the next checkpoint."
    )
    forecasts = make_forecasts(observed, plan, retail, starts, new_receipts, operations, global_dev, dev, capacity)
    return plan, rationale, forecasts
