def await_submitted_advance(request_id):
    noted_pending = False
    while True:
        result = json.loads(capture("request-status", request_id).stdout)
        phase = result.get("status")
        if phase == "completed" and result.get("result", {}).get("success"):
            return result["result"]["dashboard"]
        if phase != "pending":
            raise RuntimeError(f"Advance {request_id} status is {result}")
        status = read_status()
        if not status["server_running"]:
            raise RuntimeError(f"Simulator stopped while advance {request_id} was pending.")
        if not noted_pending:
            print(f"Advance {request_id} is pending after the CLI disconnected. Checking its existing request status.", flush=True)
            noted_pending = True
        time.sleep(45)


def advance_to(until):
