        ), None)
        if known_budget is not None:
            baseline = min(baseline * 1.35, known_budget * 1.02)
        if thread["turn_number"] > 0:
            baseline *= 0.88
        if thread["thread_type"] in ("renewal", "churn_prevention"):
            baseline *= 0.88
