def make_forecasts(observed, plan, retail, starts, new_receipts, total_operations, global_dev, dev, capacity):
    day = observed["day"]
    prices = plan.get("prices") or {name: observed["config"][f"price_{name}"] for name in PLANS}
    recent = Counter()
    for row in observed["ledger"]:
        if row["day"] > day - 7:
            recent[row["category"]] += row["amount"]
    active = sum(group["active"] for group in retail.values())
    current_mrr = sum(row["active"] * prices[row["plan"]] for row in observed["retail"])
    current_mrr += sum(row["mrr"] for row in observed["enterprise_book"])
    due = sum(
        row["seats"] * prices[row["plan"]] if row["customer_type"] == "small" else row["mrr"]
        for row in observed["due"]
    )
    adjusted_acquisitions = sum(starts.values())
    cap_growth = min(adjusted_acquisitions, 130000)
    compute = -recent["compute"] * (active + cap_growth / 2) / max(1, active - sum(
        group["joined"] for group in retail.values()
    ) / 2)
    ad_spend = sum(amount for group in plan.get("advertising", {}).get("targeted_spend", {}).values() for amount in group.values())
    if "advertising" not in plan:
        ad_spend = observed["config"]["spend_advertising"]
    fixed = 7 * (total_operations + global_dev + sum(dev.values()) + CAPACITY_COSTS[capacity] + ad_spend)
    uncertain_receipts = new_receipts * 0.95
    near_gain = due * 0.96 + uncertain_receipts - fixed - compute + recent["ad_revenue"] - adjusted_acquisitions * 0.65
    daily_run_rate = current_mrr / 30 - (
        compute / 7 + total_operations + CAPACITY_COSTS[capacity] + global_dev + sum(dev.values())
    )
    discovery_cost = 25000 * plan.get("discovery_attempts", 0)
    project_cost = sum(round(tier * 166666.7) for tier in plan.get("research", []))
    cash = observed["cash"] - discovery_cost - project_cost
    growth_cash = max(0, uncertain_receipts - ad_spend * 7)
    forecasts = []
    for horizon in (7, 28, 84, 182):
        modeled_days = min(horizon, 500 - day)
        if horizon == 7:
            point = cash + near_gain * modeled_days / 7
            width = max(15000, min(0.6, 40000 / max(active, 1) + 0.13) * abs(uncertain_receipts) + 0.07 * due)
        else:
            growth = growth_cash * min(17, modeled_days / 7) * (0.8 + min(1.7, modeled_days / 120))
            point = cash + modeled_days * daily_run_rate * 0.98 + growth
            width = max(45000, abs(point - cash) * (0.22 + min(0.35, horizon / 320)))
        lower = max(0, point - width)
        point = max(lower, point)
        forecasts.extend(round(value, 2) for value in (point, lower, point + width))
    return forecasts


